insert into pipeline.course_fact_source_qualifications(country_id,source_id,source_key,authority_name,source_class,provider_cricos,mapping_strategy,evidence_strategy,qualification_status,admitted_domains,notes,metadata)
select s.country_id,s.id,'au_federation_official_course_pages','Federation University Australia','provider_first_party','00103D','exact CRICOS Course code from Layer 1 plus guarded first-party title match; reject identity mismatch','retained Native Evidence + Normalised Evidence + deterministic candidate lineage','bounded',array['official_course_url','international_fee','intake','english_requirement']::text[],'M2.1 bounded 5-Course Federation University trial only. No Search/publication admission. Fee application requires strong international-fee candidate; domestic CSP values are not admitted.',jsonb_build_object('gate','M2.1-L2-PLATFORM','change_control_ref','CF-CHG-20260823-029','apply_admitted',true,'search_admitted',false,'identity_authority',false,'bounded_trial_size',5,'qualified_at',now())
from pipeline.layer2_source_profiles p join pipeline.sources s on s.id=p.source_id
where p.profile_key='au-federation-course-detail'
and not exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.provider_cricos='00103D');
